frappe.ui.form.on('Item Group Rate Master', {
	item_group: function(frm) {
        if (frm.doc.item_group) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Item Group',
                    filters: {
                        name: frm.doc.item_group
                    },
                    fieldname: 'price'
                },
                callback: function(r) {
                    if (r.message) {
                        price_total=frm.doc.price_master + r.message.price
                        frm.set_value('price_master', price_total);
                    }
                }
            });
        }
    }
})

frappe.ui.form.on('Sales Order Item', {
  item_code: function(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (row.item_code ) {
      frappe.call({
        method: "frappe.client.get_value",
        args: {
          doctype: "Bin",
          filters: {
            item_code: row.item_code

          },
          fieldname: "actual_qty"
        },
        callback: function(r) {
            console.log("r.message.actual_qty::"+r.message.actual_qty)
          if (r.message) {
            frappe.model.set_value(cdt, cdn, "available_stock", r.message.actual_qty);
          } else {
            frappe.model.set_value(cdt, cdn, "available_stock", 0);
          }
        }
      });
    }
  },

});

frappe.ui.form.on("Sales Order", {
  refresh: function(frm) {
    if (frm.doc.docstatus === 0) {
