frappe.ui.form.on('Update Stock', {
  refresh(frm) {
    if (frm.doc.docstatus === 0) {
      frm.add_custom_button('Select from Available Stock', () => {
          frm.doc.items = [];
        open_stock_selector(frm);
      });
    }
  }
});


function open_stock_selector(frm) {
    if (!frm.doc.customer) {
        frappe.msgprint("Please select a Customer before choosing items from stock.");
        return;
    }
  frappe.call({
    method: "erpnext.selling.doctype.sales_order.sales_order.get_individual_stock_entries",
    args: { customer: frm.doc.customer,company:frm.doc.company },
    callback: function(r) {
      const items = r.message || [];

      const dialog = new frappe.ui.Dialog({
        title: "Select Available Stock",
        fields: [
          { fieldtype: "Data", label: "Search Item Name", fieldname: "search_name" },
          { fieldtype: "Float", label: "Exact Quantity", fieldname: "search_qty" },
          { fieldtype: "HTML", fieldname: "stock_table" }
        ],
        primary_action_label: "Add Selected",
        primary_action() {
          const selected = Array.from(dialog.fields_dict.stock_table.$wrapper.find("input:checked"))
          .map(input => items[parseInt(input.dataset.index)]);

        selected.forEach(item => {
          frm.add_child("items", {
            item_code: item.item_code,
            item_name: item.item_name,
            qty: item.actual_qty,
            rate: parseFloat(item.item_price || 0).toFixed(2),
            amount: item.actual_qty * item.item_price,
          });
        });

        frm.refresh_field("items");
        calculate_totals(frm)
          dialog.hide();
        }
      });

      let debounceTimer;

      dialog.fields_dict.search_name.$wrapper.find("input").on("input", function () {
        const value = this.value;
        if (value.length >= 2) {
          clearTimeout(debounceTimer);
          debounceTimer = setTimeout(() => {
            filter_stock(dialog, items);
          }, 1000);
        }
      });

      dialog.fields_dict.search_qty.$wrapper.find("input").on("input", function () {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
          filter_stock(dialog, items);
        }, 1000);
      });

      dialog.show();
      render_stock_table(dialog, items);
    }
  });
}

function filter_stock(dialog, items) {
  const name = (dialog.get_value("search_name") || "").toLowerCase();
  const qty = dialog.get_value("search_qty");

  const filtered = items.filter(item => {
    const name_match = name ? item.item_name.toLowerCase().includes(name) : true;
    const qty_match = qty ? item.actual_qty === qty : true;
    return name_match && qty_match;
  });

  render_stock_table(dialog, filtered);
}

function render_stock_table(dialog, filtered) {
  const html = `
    <table class="table table-bordered">
      <thead>
        <tr>
          <th>Select</th>
          <th>Item</th>
          <th>Qty (kg)</th>
          <th>Price (₹)</th>
        </tr>
      </thead>
      <tbody>
        ${filtered.map((item, i) => `
          <tr>
            <td><input type="checkbox" data-index="${i}"></td>
            <td>${item.item_name}</td>
            <td>${item.actual_qty}</td>
            <td>${parseFloat(item.item_price || 0).toFixed(2)}</td>
          </tr>
        `).join("")}
      </tbody>
    </table>
  `;
  dialog.fields_dict.stock_table.$wrapper.html(html);
}

frappe.ui.form.on('Update Stock Item', {
  items_add: calculate_totals,
  items_remove: calculate_totals,
  items_on_form_rendered: calculate_totals,
  validate: calculate_totals
});

function calculate_totals(frm) {
  let total_qty = 0;
  let total_amount = 0;

  (frm.doc.items || []).forEach(row => {
    total_qty += row.qty || 0;
    total_amount += row.amount || (row.qty * row.rate) || 0;
  });

  frm.set_value("total_qty", total_qty);
  frm.set_value("total_amount", total_amount);
}

frappe.ui.form.on('Update Stock Item', {
  rate: calculate_totals
});
